insert into programs (id, code, name, area, school, key_rules, source_url) values
  ('96c442f9-c5d2-5355-9c14-d790dccbadac', 'CS-BA', 'BA in Computer Science', 'Computer Science', 'College of Arts & Sciences', '15 courses; Group C (CS 320, 332, 350) cannot be transferred', 'https://www.bu.edu/academics/cas/programs/computer-science/ba/'),
  ('ccc5a7c7-bae6-5dbf-8c3c-fd6a9452a7f6', 'EC-BA', 'BA in Economics', 'Economics', 'College of Arts & Sciences', '12 courses; max 4 courses at 200+ level transferred after matriculation', 'https://www.bu.edu/academics/cas/programs/economics/ba'),
  ('57460a9d-1d55-5d65-925b-5b39542f3a0c', 'PS-BA', 'BA in Psychology', 'Psychology', 'College of Arts & Sciences', 'PS 101 + 9 principal courses; PS 231 required', 'https://www.bu.edu/academics/cas/programs/psychology/ba/'),
  ('b1e3db6c-55f3-5deb-b40e-43c949686067', 'BI-BA', 'BA in Biology', 'Biology', 'College of Arts & Sciences', 'At least 5 BI courses beyond BI 107/108 must be taken at BU', 'https://www.bu.edu/academics/cas/departments/biology/'),
  ('1e2954da-dacb-5301-9d7c-e8ef0d51760b', 'MA-BA', 'BA in Mathematics', 'Mathematics', 'College of Arts & Sciences', 'Calculus sequence MA 123/124/225 plus MA 242', 'https://www.bu.edu/math/undergraduate/faqs-and-forms/');
insert into courses (id, institution_id, code, title, program_area, requirement_type, credits, description, learning_outcomes, verified, data_origin) values
  ('758be3c4-d002-5395-b474-c5b28cee9878', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS CS 111', 'Introduction to Computer Science 1', 'Computer Science', 'Core (Group A)', 4, 'Introduction to programming and computational problem solving in a high-level language (Python). Covers variables, control flow, functions, recursion, lists and dictionaries, file input/output, an introduction to classes and objects, and testing and debugging practice.', array['Write, test and debug programs of moderate size','Decompose problems into functions, including recursive solutions','Use lists, dictionaries and simple classes']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('b4fa5879-ec21-52a0-9132-6fc35862f219', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS CS 112', 'Introduction to Computer Science 2', 'Computer Science', 'Core (Group A)', 4, 'Second programming course focused on data structures and their analysis, taught in an object-oriented language (Java). Covers linked lists, stacks, queues, trees, binary search trees, heaps, hash tables and an introduction to graphs, with Big-O analysis of each operation.', array['Implement and use core data structures','Analyse time and space complexity using Big-O notation','Select an appropriate data structure for a given problem']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('99e0d407-e97b-5043-aef1-a112ad2d173d', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS CS 131', 'Combinatoric Structures', 'Computer Science', 'Core (Group A)', 4, 'Mathematical foundations of computer science: propositional and predicate logic, proof techniques, induction, sets, functions and relations, counting and combinatorics, recurrence relations, graphs and trees, and an introduction to discrete probability.', array['Construct direct, contradiction and induction proofs','Solve counting problems and recurrences','Reason about graphs and basic discrete probability']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('bb877f48-1027-50d7-86c8-0b547f127737', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS CS 210', 'Computer Systems', 'Computer Science', 'Core (Group A)', 4, 'How programs execute on real machines: data representation, C programming, assembly language, memory hierarchy and caches, linking, processes and an introduction to concurrency.', array['Write and debug C programs','Explain how high-level code maps to machine instructions','Reason about memory and cache performance']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('deaf5be9-d989-5eec-931a-6369ee91e5c4', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS CS 330', 'Introduction to the Analysis of Algorithms', 'Computer Science', 'Core (Group A)', 4, 'Design and analysis of algorithms: divide and conquer, greedy methods, dynamic programming, graph algorithms (search, shortest paths, minimum spanning trees), network flow and NP-completeness, with proofs of correctness and running time.', array['Design algorithms using standard paradigms','Prove correctness and running time','Recognise intractable problems']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('a13a421a-dc48-52a3-aaf1-8530876e4894', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS CS 132', 'Geometric Algorithms', 'Computer Science', 'Group B (choose)', 4, 'Linear algebra from a computational perspective: vectors, matrices, linear transformations, eigenvalues and least squares, applied to graphics, data analysis and machine learning, with programming assignments in Python.', array['Perform core matrix computations','Apply linear algebra to computational problems','Implement linear-algebra algorithms in code']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('156eb1f3-e208-55f8-9f9f-b78f73bd75f0', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS CS 235', 'Algebraic Algorithms', 'Computer Science', 'Group B (choose)', 4, 'Algorithms for algebraic structures: modular arithmetic, groups, rings and fields, polynomials, and applications to cryptography and error-correcting codes.', array['Compute in modular and polynomial arithmetic','Explain algebraic structures used in cryptography','Implement basic cryptographic algorithms']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('e2649dc7-ff03-5ff6-8ebf-fc541c1206e3', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS CS 237', 'Probability in Computing', 'Computer Science', 'Group B (choose)', 4, 'Probability for computing: sample spaces, conditional probability, random variables, expectation and variance, common distributions, tail bounds and applications to randomised algorithms and simulation.', array['Compute probabilities and expectations','Apply common distributions and tail bounds','Analyse simple randomised algorithms']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('e2ede3b4-b558-5d13-a683-6328936eac39', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS CS 320', 'Concepts of Programming Languages', 'Computer Science', 'Group C (BU only)', 4, 'Concepts of programming languages: syntax and semantics, interpreters, scope, type systems, functional programming and language design trade-offs.', array['Build a small interpreter','Explain type systems and scoping rules','Compare language design choices']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('93433186-489c-5f2e-a502-649919de1a02', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS CS 332', 'Elements of the Theory of Computation', 'Computer Science', 'Group C (BU only)', 4, 'Theory of computation: finite automata, regular languages, context-free grammars, Turing machines, decidability and an introduction to the complexity classes P and NP.', array['Construct automata and grammars','Prove languages non-regular or undecidable','Explain P versus NP']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('4a804ef4-5981-5ffa-b9a7-360debf46bf3', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS CS 350', 'Fundamentals of Computing Systems', 'Computer Science', 'Group C (BU only)', 4, 'Fundamentals of computing systems: performance modelling, queuing, scheduling, concurrency and synchronisation, and operating-system resource management.', array['Model system performance','Write correct concurrent code','Explain OS resource management']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('9d7f0e0d-a7c1-5096-aa17-d68a8353eb88', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS EC 101', 'Introductory Microeconomic Analysis', 'Economics', 'Intro', 4, 'Principles of microeconomics: supply and demand, consumer and producer behaviour, market structures, market failure and the role of government.', array['Use supply and demand to analyse markets','Compare market structures','Evaluate policy responses to market failure']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('88915821-d3b7-555b-9992-7e5524b6f2f6', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS EC 102', 'Introductory Macroeconomic Analysis', 'Economics', 'Intro', 4, 'Principles of macroeconomics: national income accounting, unemployment, inflation, economic growth, money and banking, and fiscal and monetary policy.', array['Interpret macroeconomic indicators','Explain fiscal and monetary policy','Analyse short-run fluctuations']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('179aac0e-610b-576d-a261-b5cfc69e83fc', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS EC 201', 'Intermediate Microeconomic Analysis', 'Economics', 'Core', 4, 'Intermediate microeconomic theory using calculus: consumer choice, production and cost, general equilibrium, game theory and information economics.', array['Solve constrained optimisation problems','Analyse strategic interaction','Evaluate welfare outcomes']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('558751ae-c8e1-5cf5-b48b-ac395a6bb0f2', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS EC 202', 'Intermediate Macroeconomic Analysis', 'Economics', 'Core', 4, 'Intermediate macroeconomic theory: growth models, business cycles, consumption and investment, open-economy macroeconomics and stabilisation policy.', array['Use formal models of growth and cycles','Analyse policy in open economies','Interpret macroeconomic data']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('d3e9a6e6-6945-5676-9479-19f57a4325b8', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS EC 203', 'Empirical Economics 1', 'Economics', 'Core', 4, 'Probability and statistics for economics: descriptive statistics, probability distributions, sampling, estimation, hypothesis testing and simple linear regression using statistical software.', array['Summarise economic data','Conduct hypothesis tests','Estimate and interpret simple regressions']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('fada9152-6814-577a-ba7b-8bbd93fa4e73', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS EC 204', 'Empirical Economics 2', 'Economics', 'Core', 4, 'Econometrics: multiple regression, inference, specification, heteroskedasticity, instrumental variables, panel data and causal inference, with an independent empirical project.', array['Estimate and test multiple regression models','Apply IV and panel methods','Complete an empirical research project']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('809d2139-dd1e-588a-b84e-00e789efec21', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS PS 101', 'General Psychology', 'Psychology', 'Prerequisite', 4, 'Survey of psychology as a science: research methods, biological bases of behaviour, sensation and perception, learning, memory, development, personality, social behaviour and psychological disorders.', array['Describe major areas of psychology','Explain basic research methods','Apply psychological concepts to everyday behaviour']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('2a4fb1cd-462f-58b2-af00-a48de839b948', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS PS 211', 'Experimental Design in Psychology', 'Psychology', 'Design & Statistics', 4, 'Research methods in psychology: experimental design, validity, ethics and the statistics used to analyse experiments (t-tests, ANOVA), with lab reports written in APA style.', array['Design a controlled experiment','Analyse results with t-tests and ANOVA','Write an APA-style lab report']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('3b1d2509-061a-57d8-9961-3b9fbcec6c33', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS PS 231', 'Physiological Psychology', 'Psychology', 'Required principal', 4, 'Biological bases of behaviour: neurons and neurotransmission, neuroanatomy, hormones, sensory and motor systems, sleep, motivation, emotion and the effects of drugs.', array['Explain neural communication','Relate brain systems to behaviour','Evaluate biological explanations of behaviour']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('19162c88-8440-5604-b7b2-7aa70a3fb68b', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS PS 222', 'Perception and Behavior', 'Psychology', 'Group A', 4, 'Perception: how sensory systems transform physical energy into experience, with emphasis on vision and hearing, psychophysics and perceptual organisation.', array['Explain sensory transduction','Apply psychophysical methods','Describe theories of perception']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('9dbd6595-7c9e-5786-a2ad-a54ab42967cb', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS PS 336', 'Introduction to Cognitive Psychology', 'Psychology', 'Group A', 4, 'Cognitive psychology: attention, memory, categorisation, language, problem solving, reasoning and decision making.', array['Describe models of memory and attention','Evaluate cognitive experiments','Apply cognitive principles']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('bbb17259-0bbb-579f-b163-98072aaed001', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS PS 241', 'Developmental Psychology', 'Psychology', 'Group B', 4, 'Developmental psychology from infancy through adolescence: physical, cognitive, language, social and emotional development, and research methods for studying children.', array['Describe developmental milestones','Compare developmental theories','Evaluate developmental research']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('72a84483-f1ea-53ff-a76a-1b304e2901c1', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS PS 251', 'Psychology of Personality: Theories and Application', 'Psychology', 'Group B', 4, 'Theories of personality: psychodynamic, trait, humanistic, social-cognitive and biological approaches, with personality assessment and applications.', array['Compare personality theories','Evaluate personality assessments','Apply theories to case studies']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('ad2d2a25-264b-563a-b562-cfd286ffc475', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS PS 261', 'Social Psychology', 'Psychology', 'Group B', 4, 'Social psychology: social cognition, attitudes, persuasion, conformity, group processes, prejudice, aggression and prosocial behaviour.', array['Explain core social-psychology phenomena','Evaluate classic studies','Apply concepts to real situations']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('5b88dce7-8b04-534e-a89b-04ef561443e6', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS PS 371', 'Psychopathology', 'Psychology', 'Group B', 4, 'Psychopathology: classification, causes and treatment of psychological disorders, including anxiety, mood, psychotic and personality disorders.', array['Describe major disorders','Compare causal models','Evaluate treatment approaches']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('dbe1c66f-14b6-5dbe-8474-0c67ef8429a7', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS BI 107', 'Biology 1', 'Biology', 'Intro', 4, 'First-semester introductory biology with laboratory: chemistry of life, cell structure, metabolism, cell division, Mendelian and molecular genetics.', array['Explain cell structure and function','Describe metabolism and genetics','Conduct and report basic lab experiments']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('1bee9b13-cd76-54a1-a6b1-0710ca03ef71', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS BI 108', 'Biology 2', 'Biology', 'Intro', 4, 'Second-semester introductory biology with laboratory: evolution, biodiversity, organismal physiology and ecology.', array['Explain evolutionary mechanisms','Compare organism systems','Analyse ecological interactions']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('ec0c2638-8d7c-59ac-b5ba-e13077cf344a', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS BI 203', 'Cell Biology', 'Biology', 'Core', 4, 'Cell biology: membranes, organelles, protein trafficking, cytoskeleton, cell signalling, cell cycle and cell death.', array['Explain cellular processes','Interpret experimental cell-biology data','Relate cell function to disease']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('11b1d9b5-5727-597d-b1e6-a8ed8dae4fdf', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS BI 206', 'Genetics', 'Biology', 'Core', 4, 'Genetics: Mendelian inheritance, linkage and mapping, chromosomes, gene regulation, mutation, population genetics and genomic methods.', array['Solve genetics problems','Explain gene regulation','Interpret genomic data']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('993b328b-5770-5393-914e-d88367210cc2', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS CH 101', 'General Chemistry 1', 'Biology', 'Supporting (Chemistry)', 4, 'General chemistry I with laboratory: atomic structure, periodic trends, bonding, stoichiometry, gases, thermochemistry and solutions.', array['Solve stoichiometry problems','Explain bonding and periodic trends','Perform quantitative lab work']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('ae0139fb-a748-51fc-9fdf-b0c2ead4f290', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS CH 102', 'General Chemistry 2', 'Biology', 'Supporting (Chemistry)', 4, 'General chemistry II with laboratory: kinetics, equilibrium, acids and bases, thermodynamics and electrochemistry.', array['Solve equilibrium and kinetics problems','Explain thermodynamic principles','Perform titrations and analyses']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('803a8458-bfd3-5c88-b52e-9dca63b0995a', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS CH 203', 'Organic Chemistry 1', 'Biology', 'Supporting (Chemistry)', 4, 'Organic chemistry I with laboratory: structure and bonding, stereochemistry, nomenclature, substitution and elimination reactions, alkenes and alkynes.', array['Draw and name organic structures','Predict reaction mechanisms','Perform organic lab techniques']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('130a5bbd-4d3e-516c-aafe-071e939fa402', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS CH 204', 'Organic Chemistry 2', 'Biology', 'Supporting (Chemistry)', 4, 'Organic chemistry II with laboratory: aromatic compounds, carbonyl chemistry, spectroscopy, multistep synthesis and biomolecules.', array['Predict carbonyl and aromatic reactions','Interpret NMR and IR spectra','Plan multistep syntheses']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('69ba7b93-f269-5f90-8165-3572e0fc17e6', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS MA 123', 'Calculus I', 'Mathematics', 'Lower division', 4, 'Differential calculus: limits, continuity, derivatives and their applications, and an introduction to integration.', array['Compute limits and derivatives','Apply derivatives to optimisation and related rates','Evaluate basic integrals']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('e4ce65f1-f2fc-51b9-8b82-b3a692eb7b48', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS MA 124', 'Calculus II', 'Mathematics', 'Lower division', 4, 'Integral calculus: techniques of integration, applications of integrals, sequences and series, and power series.', array['Apply integration techniques','Determine convergence of series','Use power series']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('7fcb66a1-bcff-59a2-9cef-9a4e11068ad9', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS MA 225', 'Multivariate Calculus', 'Mathematics', 'Lower division', 4, 'Multivariable calculus: vectors, partial derivatives, multiple integrals, and vector calculus (Green''s, Stokes'' and divergence theorems).', array['Compute partial derivatives and multiple integrals','Apply vector-calculus theorems','Solve multivariable optimisation problems']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('174012d6-e350-5149-a070-6eb9a17ea4cd', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS MA 242', 'Linear Algebra', 'Mathematics', 'Lower division', 4, 'Linear algebra: systems of linear equations, matrices, vector spaces, linear transformations, determinants, eigenvalues and orthogonality.', array['Solve linear systems','Work with vector spaces and transformations','Compute eigenvalues and eigenvectors']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('29e12d80-d6f8-5910-b3ff-1652cfacaa80', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS MA 226', 'Differential Equations', 'Mathematics', 'Lower division', 4, 'Ordinary differential equations: first-order equations, linear higher-order equations, systems, Laplace transforms and applications.', array['Solve first- and higher-order ODEs','Use Laplace transforms','Model physical systems with ODEs']::text[], 'Check', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('d0fdb102-9c99-5e58-9941-a150b6a4e4c7', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS MA 293', 'Discrete Mathematics', 'Mathematics', 'Lower division', 4, 'Discrete mathematics: logic, proof techniques, sets, functions, relations, combinatorics, graph theory and elementary number theory.', array['Write rigorous proofs','Solve combinatorial problems','Apply graph theory and number theory']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('8aa5fe7a-1b7b-5cfb-b145-22f3594fd4b6', '69c35622-4e41-57b4-b2be-e25585a20d5f', 'CAS MA 581', 'Probability', 'Mathematics', 'Upper division', 4, 'Calculus-based probability: axioms, conditional probability, discrete and continuous random variables, joint distributions, expectation, limit theorems.', array['Compute probabilities with calculus','Work with joint distributions','Apply limit theorems']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('6c2d3d70-0121-5172-9b5c-5b4b3f452d10', '1ecc7c3f-476c-5158-ac5a-2b61dac8238d', 'CS 2000', 'Introduction to Program Design and Implementation', 'Computer Science', null, 5, 'Introduction to programming and computational problem solving in a high-level language (Python). Covers variables, control flow, functions, recursion, lists and dictionaries, file input/output, an introduction to classes and objects, and testing and debugging practice.', array['Write, test and debug programs of moderate size','Decompose problems into functions, including recursive solutions','Use lists, dictionaries and simple classes']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('e701133b-70e3-537e-af3e-5163dd1315ec', '1ecc7c3f-476c-5158-ac5a-2b61dac8238d', 'CS 2100', 'Program Design and Implementation 1', 'Computer Science', null, 5, 'Systematic program design using design recipes, data definitions and test-first development. Emphasises functional decomposition and abstraction; lists and trees are introduced as data, but asymptotic analysis and hash tables are not covered.', array['Design programs from data definitions','Write tests before code','Use abstraction to remove duplication']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('a62d3f35-c3d8-5df2-ad5b-8271607e87e2', '1ecc7c3f-476c-5158-ac5a-2b61dac8238d', 'CS 3100', 'Program Design and Implementation 2', 'Computer Science', null, 5, 'Object-oriented program design: classes, interfaces, inheritance, generics, common design patterns and team software projects with unit testing.', array['Design class hierarchies','Apply common design patterns','Deliver a tested multi-module project']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('ef5bc594-da83-52d3-a280-2bd81ad28266', '1ecc7c3f-476c-5158-ac5a-2b61dac8238d', 'CS 1800', 'Discrete Structures', 'Computer Science', null, 4, 'Mathematical foundations of computer science: propositional and predicate logic, proof techniques, induction, sets, functions and relations, counting and combinatorics, recurrence relations, graphs and trees, and an introduction to discrete probability.', array['Construct direct, contradiction and induction proofs','Solve counting problems and recurrences','Reason about graphs and basic discrete probability']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('0228bc7a-ed7e-50eb-afbf-dfca5d998f2e', '1ecc7c3f-476c-5158-ac5a-2b61dac8238d', 'CS 2700', 'Data Structures and Analysis', 'Computer Science', null, 5, 'Data structures with formal analysis: lists, trees, balanced search trees, heaps, hash tables and graphs, with proofs of running time and an introduction to amortised analysis. Includes a weekly lab.', array['Implement and analyse data structures','Prove running-time bounds','Choose structures for performance requirements']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
  ('2a0cca89-69bc-5389-8682-f66c30afdce0', '1ecc7c3f-476c-5158-ac5a-2b61dac8238d', 'CS 3000', 'Algorithms and Data', 'Computer Science', null, 4, 'Design and analysis of algorithms: divide and conquer, greedy methods, dynamic programming, graph algorithms (search, shortest paths, minimum spanning trees), network flow and NP-completeness, with proofs of correctness and running time.', array['Design algorithms using standard paradigms','Prove correctness and running time','Recognise intractable problems']::text[], 'Yes', 'Code/title/credits from supplied workbook; description & outcomes synthetic'),
